import Foundation

/// A radio station. Fields mirror the original app's `radio_id`, `name`, `desc`,
/// `region`, `img_url` and `urlString` model (ZSVRadionItem in the shipped IPA).
struct Station: Identifiable, Codable, Hashable {
    var id: String { radio_id }
    let radio_id: String
    let name: String
    let desc: String
    let region: String
    let url: String
    let img_url: String?
    let tag: String?

    enum CodingKeys: String, CodingKey {
        case radio_id, name, desc, region, url, img_url, tag
    }
}

