extension StationData {
    /// 原 App 官方在线列表接口（JSON，含 radio 数组）
    static let remoteURL = "https://fm.oaife.com/radio.json"

    /// 分组用的地区列表（按首次出现顺序）
    static var regions: [String] {
        var seen = Set<String>(); var out = [String]()
        for s in all where seen.insert(s.region).inserted { out.append(s.region) }
        return out
    }

    /// 启动时尝试从官方接口拉取最新列表，失败则返回内置目录
    static func load(completion: @escaping ([Station]) -> Void) {
        guard let url = URL(string: remoteURL) else { completion(all); return }
        URLSession.shared.dataTask(with: url) { data, _, _ in
            let result: [Station]
            if let data = data,
               let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
               let arr = json["radio"] as? [[String: Any]] {
                let parsed = arr.compactMap { d -> Station? in
                    guard let id = d["radio_id"] as? String,
                          let name = d["name"] as? String,
                          let url = d["url"] as? String, !url.isEmpty else { return nil }
                    return Station(radio_id: id, name: name,
                                   desc: d["desc"] as? String ?? "",
                                   region: d["region"] as? String ?? "其他",
                                   url: url, img_url: d["img_url"] as? String, tag: nil)
                }
                result = parsed.isEmpty ? all : parsed
            } else {
                result = all
            }
            DispatchQueue.main.async { completion(result) }
        }.resume()
    }
}
